# Long Beach Airport, CA — NOAA 1971-2000 normals (via ggweather). Converted F->C, in->mm.
F=lambda f: round((f-32)*5/9,1)
LB_TX=[F(x) for x in [68.0,68.5,68.9,72.7,74.0,78.3,82.9,84.6,83.1,78.9,73.4,68.8]]
LB_TN=[F(x) for x in [46.0,48.1,50.4,53.2,57.8,61.3,64.6,65.6,63.7,58.3,50.1,45.3]]
LB_P =[round(x*25.4,1) for x in [2.95,3.01,2.43,0.60,0.23,0.08,0.02,0.10,0.24,0.40,1.12,1.76]]

def km(a,b,c,d): return math.hypot((a-c)*111.0,(b-d)*111.0*math.cos(math.radians((a+c)/2)))

def interp(lat,lon,k=3,p=2):
    ds=sorted(((km(lat,lon,v[0],v[1]),n) for n,v in S.items()))[:k]
    if ds[0][0]<1: ds=[ds[0]]
    w=[1/max(d,1)**p for d,_ in ds]; W=sum(w)
    out=[]
    for idx in (3,4,5):
        out.append([sum(wi*S[n][idx][m] for wi,(_,n) in zip(w,ds))/W for m in range(12)])
    return out, ds[0]

def metrics(tx,tn,pr):
    T=[(a+b)/2 for a,b in zip(tx,tn)]
    dry=[m for m in range(12) if pr[m] < 2*T[m]]           # Bagnouls-Gaussen dry month
    deficit=sum(2*T[m]-pr[m] for m in dry)
    summer=[11,0,1,2]                                        # Dec-Mar
    return dict(annual=round(sum(pr)), summerRain=round(sum(pr[m] for m in summer)),
                dryMonths=len(dry), deficit=round(deficit), tmaxHot=round(max(tx),1),
                tminCold=round(min(tn),1), tmeanHot=round(max(T),1))

